export const LUNCH_START = 750;
export const LUNCH_END = 790;

export function nextStart(log: Visit[], day: number, from: number, service: Service): number {
  const first = nextStartIgnoringLunch(log, day, from, service);
  if (first === NO_START) return NO_START;
  const length = SLOTS[service] * SLOT_MIN;
  if (first < LUNCH_END && first + length > LUNCH_START) {
    // Any later start before lunch ends would overlap lunch too, so resume at 13:10.
    return nextStartIgnoringLunch(log, day, Math.max(from, LUNCH_END), service);
  }
  return first;
}

